<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Services\Dezerx\Subdomains\Subdomains; use Pterodactyl\Services\Dezerx\Subdomains\CloudflareClient; use Pterodactyl\Services\Dezerx\Subdomains\SubdomainManager; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Subdomains\SubdomainRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Subdomains\SubdomainWriteRequest; class SubdomainController extends ClientApiController { public function __construct(private readonly SubdomainManager $manager) { parent::__construct(); } public function index(SubdomainRequest $request, Server $server, CloudflareClient $cloudflare): JsonResponse { return new JsonResponse([ 'available' => $cloudflare->configured(), 'max' => Subdomains::maxPerServer(), 'domains' => $this->manager->domains($server), 'anyDomains' => $this->manager->offersAny(), 'allocations' => $this->allocations($server), 'records' => SubdomainManager::recordsFor($server->id), ]); } public function store(SubdomainWriteRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'subdomain' => ['required', 'string', 'max:32'], 'domain' => ['required', 'integer'], 'allocation' => ['required', 'integer'], ]); $chosen = null; foreach ($this->allocations($server) as $allocation) { if ($allocation['id'] === (int) $data['allocation']) { $chosen = $allocation; } } if ($chosen === null) { return new JsonResponse(['errors' => [[ 'code' => 'InvalidAllocation', 'detail' => 'That is not one of this server\'s addresses.', ]]], 422); } $result = $this->manager->claim( (int) $data['domain'], $data['subdomain'], $server, $request->user()->id, $this->target($chosen), $chosen['port'], ); if (!$result['ok']) { return new JsonResponse(['errors' => [[ 'code' => 'SubdomainRefused', 'detail' => $result['message'], ]]], 422); } Activity::event('server:subdomain.claim') ->subject($server) ->property('name', $result['message']) ->log(); return new JsonResponse([ 'message' => $result['message'], 'records' => SubdomainManager::recordsFor($server->id), ]); } public function destroy(SubdomainWriteRequest $request, Server $server, int $record): JsonResponse { $result = $this->manager->release($record, $server->id); if (!$result['ok']) { return new JsonResponse(['errors' => [[ 'code' => 'SubdomainMissing', 'detail' => $result['message'], ]]], 404); } Activity::event('server:subdomain.release')->subject($server)->log(); return new JsonResponse([ 'message' => $result['message'], 'records' => SubdomainManager::recordsFor($server->id), ]); } private function allocations(Server $server): array { $out = []; foreach ($server->allocations as $allocation) { $ip = trim((string) $allocation->ip); $port = (int) $allocation->port; if ($ip === '' || $port === 0) { continue; } $out[] = [ 'id' => (int) $allocation->id, 'host' => trim((string) $allocation->ip_alias) ?: $ip, 'ip' => $ip, 'port' => $port, 'primary' => (int) $allocation->id === (int) $server->allocation_id, ]; } usort($out, fn (array $a, array $b) => ($b['primary'] <=> $a['primary']) ?: ($a['port'] <=> $b['port'])); return $out; } private function target(array $allocation): string { $host = $allocation['host']; if (filter_var($host, FILTER_VALIDATE_IP) !== false) { return $host; } if (str_contains($host, '.') && filter_var($host, FILTER_VALIDATE_DOMAIN, FILTER_FLAG_HOSTNAME) !== false) { return $host; } return $allocation['ip']; } } 